const q = [3, 1, 2];
const docs = { d0: [6, 2, 4], d1: [1, 5, 1], d2: [2, 1, 3], d3: [0, 4, 0], d4: [4, 1, 1] };
function dot(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }
function norm(a) { return Math.sqrt(dot(a, a)); }
const scored = Object.keys(docs).map(function (id) { return { id: id, cos: dot(q, docs[id]) / (norm(q) * norm(docs[id])) }; });
scored.sort(function (a, b) { return b.cos - a.cos; });
const top3 = scored.slice(0, 3).map(function (r) { return r.id; });
console.log('top3=' + top3.join(','));

const q = [1, 1, 0];
const docs = { a: [9, 1, 0], b: [3, 3, 0], c: [2, 1, 0] };
function dot(x, y) { let s = 0; for (let i = 0; i < x.length; i++) s += x[i] * y[i]; return s; }
function norm(x) { return Math.sqrt(dot(x, x)); }
function top1(scoreFn) {
  return Object.keys(docs).map(function (id) { return { id: id, s: scoreFn(docs[id]) }; }).sort(function (p, r) { return r.s - p.s; })[0].id;
}
const dotTop = top1(function (v) { return dot(q, v); });
const cosTop = top1(function (v) { return dot(q, v) / (norm(q) * norm(v)); });
console.log('dot_top1=' + dotTop + ' cos_top1=' + cosTop + ' agree=' + (dotTop === cosTop));
